export const universeTimelineHtml = `${ctStyles}<div class="model ct-widget" id="ct-universe-model"><div id="ct-universe-figure" class="ct-figure"><svg id="ct-universe-svg" viewBox="0 0 760 360" role="img" aria-labelledby="ct-figure-title ct-figure-desc" xmlns="http://www.w3.org/2000/svg"><title id="ct-figure-title">Universets utvikling fra kvarker til galakser</title><desc id="ct-figure-desc">Velg et tidspunkt med glideren. Figuren skifter skala mellom partikler, atomkjerner, atomer, stjerner og galakser.</desc><defs><clipPath id="ct-scene-clip"><rect x="20" y="68" width="720" height="218" rx="10"/></clipPath><radialGradient id="ct-star-glow"><stop stop-color="#fff3ba" stop-opacity=".9"/><stop offset=".2" stop-color="#f5d689" stop-opacity=".5"/><stop offset="1" stop-color="#efc472" stop-opacity="0"/></radialGradient><radialGradient id="ct-gas-glow"><stop stop-color="#689bb5" stop-opacity=".28"/><stop offset="1" stop-color="#629db5" stop-opacity="0"/></radialGradient></defs><text id="ct-scene-title" x="22" y="29" class="ct-title">Big Bang: den varme starten</text><text x="22" y="50" class="ct-subtitle">Et utsnitt av universet · Skalaen endres når nye systemer blir synlige</text><rect id="ct-scene-background" x="20" y="68" width="720" height="218" rx="10" fill="#492d33"/><g id="ct-scene" clip-path="url(#ct-scene-clip)"></g><text id="ct-scene-legend" x="22" y="313" class="ct-legend">Små fargede prikker: kvarker · Lyse prikker: andre partikler</text><text id="ct-scene-scale" x="22" y="338" class="ct-subtitle">Et mikroskopisk utsnitt av den varme partikkelsuppen.</text></svg></div><div class="controls ct-controls"><label class="control" for="ct-epoch">Tidspunkt<output id="ct-epoch-value" class="ct-phase-output">1 av 8 · Kvarker</output><input id="ct-epoch" type="range" min="0" max="7" step="1" value="0" aria-valuetext="De første mikrosekundene: kvarker"><span class="ct-slider-ends" aria-hidden="true"><span>Big Bang</span><span>I dag</span></span></label><div class="ct-step-nav"><button type="button" id="ct-previous" disabled>← Forrige</button><button type="button" id="ct-next">Neste →</button></div><p class="ct-axis-note">Glideren viser åtte stopp. Avstandene er ikke en lineær tidsakse.</p></div><div id="ct-readout" class="readout ct-readout" aria-live="polite"><span><small>Tid etter Big Bang</small><strong id="ct-age">De første mikrosekundene</strong></span><span><small id="ct-temperature-label">Temperatur i det tidlige universet</small><strong id="ct-temperature">Over 10¹² K</strong></span></div><p id="ct-description" class="model-note ct-description">Universet er svært varmt og tett. Kvarker beveger seg i en partikkelsuppe. Varmen hindrer dem i å bli værende sammen i protoner og nøytroner.<strong class="ct-cause">Når universet utvider seg, synker temperaturen.</strong></p><details class="ct-method"><summary>Om tid, temperatur og figurens skala</summary><p>Hvert bilde viser et utsnitt, med ny forstørrelse når vi går videre. Et atom vokser ikke til en galakse: mange byggesteiner danner større systemer. Tidspunkter og temperaturer er omtrentlige. Glideren begynner i universets tidlige, varme fase, ikke ved en modell av selve øyeblikket t = 0.</p><p>Etter at nøytrale atomer dannes, oppgir vi temperaturen til bakgrunnsstrålingen. Gass, stjerner og planeter kan ha helt andre temperaturer. Tyngdekraften kan varme gass som trekker seg sammen mens bakgrunnsstrålingen kjøles.</p><p>Kilder: <a href="https://science.nasa.gov/universe/overview/" target="_blank" rel="noopener">NASA – universets utvikling</a> · <a href="https://home.cern/science/physics/early-universe" target="_blank" rel="noopener">CERN – det tidlige universet</a>.</p></details></div>`;

const ctColors=['#e9ae65','#68bdd1','#ae99df'];
const ctPoint=(i,t,speed=.14)=>({x:38+((i*67.913+Math.sin(i*2.31+t*speed)*13+Math.cos(t*speed*.6+i)*6)%684+684)%684,y:88+((i*43.517+Math.cos(i*1.37+t*speed*.9)*11)%176+176)%176});
const ctDots=(count,t,{radius=1.4,color='#d7e2e9',opacity=.4,speed=.14}={})=>Array.from({length:count},(_,i)=>{const p=ctPoint(i+17,t,speed);return `<circle cx="${p.x.toFixed(2)}" cy="${p.y.toFixed(2)}" r="${radius}" fill="${color}" opacity="${opacity}"/>`;}).join('');
function ctQuarkSoup(t){
 const quarks=Array.from({length:94},(_,i)=>{const p=ctPoint(i,t,.55);return `<circle cx="${p.x.toFixed(2)}" cy="${p.y.toFixed(2)}" r="${2.1+(i%3)*.45}" fill="${ctColors[i%3]}" opacity="${.65+(i%4)*.1}"/>`;}).join('');
 return `<rect x="20" y="68" width="720" height="218" fill="#c37046" opacity=".10"/>${ctDots(58,t,{radius:1,color:'#fff1d7',opacity:.5,speed:.48})}${quarks}<text x="380" y="178" text-anchor="middle" class="ct-plot-caption">Varmt og tett overalt i utsnittet</text>`;
}
function ctBaryon(x,y,proton=true,size=12,quarks=false,angle=0){
 const fill=proton?'#e28a77':'#6bacc4',label=proton?'p⁺':'n';
 const inner=quarks?Array.from({length:3},(_,i)=>{const a=angle+i*2*Math.PI/3;return `<circle cx="${(Math.cos(a)*size*.4).toFixed(2)}" cy="${(Math.sin(a)*size*.4).toFixed(2)}" r="${size*.19}" fill="${ctColors[i]}"/>`;}).join(''):`<text x="0" y="4" text-anchor="middle" font-size="${size*1.05}" fill="#1f3440" font-weight="650">${label}</text>`;
 return `<g transform="translate(${x.toFixed(2)} ${y.toFixed(2)})"><circle r="${size}" fill="${fill}" stroke="#dcebf0" stroke-opacity=".45" stroke-width=".8"/>${inner}</g>`;
}
function ctBaryonField(t){
 const objects=Array.from({length:18},(_,i)=>{const p=ctPoint(i+2,t,.20);return ctBaryon(p.x,p.y,i%3!==0,12,true,t*.09+i);}).join('');
 return `${ctDots(40,t,{radius:1.3,color:'#dfeced',opacity:.6,speed:.3})}${objects}<g transform="translate(292 109)"><rect width="176" height="136" rx="12" fill="#253a45" fill-opacity=".95" stroke="#e5f1f0" stroke-opacity=".25"/>${ctBaryon(50,61,true,30,true,t*.08)}${ctBaryon(128,61,false,30,true,t*.08+1)}<text x="50" y="112" text-anchor="middle" font-size="14" fill="#eff3ee">Proton</text><text x="128" y="112" text-anchor="middle" font-size="14" fill="#eff3ee">Nøytron</text></g>`;
}
function ctHelium(x,y,size=8){return `<g transform="translate(${x.toFixed(2)} ${y.toFixed(2)})">${ctBaryon(-size*.6,-size*.6,true,size)}${ctBaryon(size*.6,-size*.6,false,size)}${ctBaryon(-size*.6,size*.6,false,size)}${ctBaryon(size*.6,size*.6,true,size)}</g>`;}
function ctNuclei(t){
 const hydrogen=Array.from({length:19},(_,i)=>{const p=ctPoint(i+3,t,.13);return ctBaryon(p.x,p.y,true,7.5);}).join('');
 const helium=Array.from({length:6},(_,i)=>{const p=ctPoint(i+50,t,.10);return ctHelium(p.x,p.y,8);}).join('');
 const photons=Array.from({length:3},(_,i)=>{const x=65+i*237,y=116+i*57;const points=Array.from({length:7},(_,j)=>`${x+j*12},${y+Math.sin(j*2+t*.5+i)*8}`).join(' ');return `<polyline points="${points}" stroke="#f2d999" stroke-width="1.2" fill="none" opacity=".55"/>`;}).join('');
 return `${ctDots(40,t,{radius:1.4,color:'#d4eef0',opacity:.8,speed:.18})}${photons}${hydrogen}${helium}`;
}
function ctAtom(x,y,{helium=false,radius=20,phase=0}={}){
 const nucleus=helium?ctHelium(0,0,4.1):ctBaryon(0,0,true,5);
 const electrons=Array.from({length:helium?2:1},(_,i)=>{const a=phase+i*Math.PI;return `<circle cx="${(Math.cos(a)*radius).toFixed(2)}" cy="${(Math.sin(a)*radius).toFixed(2)}" r="2.8" fill="#cfebf3"/>`;}).join('');
 return `<g transform="translate(${x.toFixed(2)} ${y.toFixed(2)})"><circle r="${radius}" fill="none" stroke="#8bb5c5" stroke-width="1.1" stroke-opacity=".65"/>${nucleus}${electrons}</g>`;
}
function ctAtoms(t){
 const atoms=Array.from({length:13},(_,i)=>{const p=ctPoint(i+5,t,.07);return ctAtom(p.x,p.y,{helium:i%5===0,radius:i%5===0?22:18,phase:t*.35+i*1.3});}).join('');
 const waves=Array.from({length:2},(_,i)=>{const y=141+i*89,x=42+((t*20+i*347)%625);return `<g transform="translate(${x.toFixed(2)} ${y})"><path d="${Array.from({length:52},(_,j)=>`${j?'L':'M'}${j} ${(4.1*Math.sin(j*.45)).toFixed(2)}`).join(' ')}" fill="none" stroke="#f2d99c" stroke-width="1.9"/><path d="M49-5l8 5-8 5" fill="none" stroke="#f2d99c" stroke-width="1.5"/></g>`;}).join('');
 return `${ctDots(33,t,{radius:.8,color:'#e8f1ef',opacity:.16,speed:.04})}${atoms}${waves}`;
}
function ctStar(x,y,r=7,opacity=1){return `<g transform="translate(${x.toFixed(2)} ${y.toFixed(2)})" opacity="${opacity}"><circle r="${r*6}" fill="url(#ct-star-glow)"/><path d="M${-r*1.8} 0H${r*1.8}M0 ${-r*1.8}V${r*1.8}" stroke="#f8e9b0" stroke-width="${Math.max(.6,r*.13)}" stroke-linecap="round"/><circle r="${r}" fill="#fff4c6"/></g>`;}
function ctFirstStars(t){
 const clouds=[[170,176,1],[392,158,.85],[608,189,1.15]].map(([x,y,s],i)=>{let p='';for(let j=0;j<5;j++){const a=j*2.4+i,contraction=.92+.05*Math.sin(t*.25+i);p+=`<ellipse cx="${(x+Math.cos(a)*28*contraction).toFixed(2)}" cy="${(y+Math.sin(a)*19*contraction).toFixed(2)}" rx="${72*s}" ry="${52*s}" fill="url(#ct-gas-glow)"/>`;}return p+ctStar(x,y,(5+i%2)*(.94+.06*Math.sin(t*.4+i)));}).join('');
 return `${ctDots(110,t,{radius:.9,color:'#c7e2ec',opacity:.35,speed:.015})}${clouds}<text x="380" y="266" text-anchor="middle" class="ct-plot-caption">Tyngdekraft samler gass → varm kjerne → fusjon</text>`;
}
function ctSpiral(x,y,size=35,angle=0,opacity=1){
 const arms=Array.from({length:2},(_,arm)=>{const steps=size>20?58:24,points=Array.from({length:steps},(_,i)=>{const fraction=i/(steps-1),a=fraction*4.958+arm*Math.PI,r=2+fraction*size;return `${i?'L':'M'}${(Math.cos(a)*r).toFixed(2)} ${(Math.sin(a)*r*.47).toFixed(2)}`;}).join(' ');return `<path d="${points}" fill="none" stroke="#b6d4e1" stroke-width="${size*.17}" stroke-linecap="round" opacity=".4"/><path d="${points}" fill="none" stroke="#d5e0e9" stroke-width="${size*.035}" stroke-linecap="round" opacity=".9"/>`;}).join('');
 return `<g transform="translate(${x.toFixed(2)} ${y.toFixed(2)}) rotate(${angle.toFixed(2)})" opacity="${opacity}"><ellipse rx="${size*.72}" ry="${size*.34}" fill="url(#ct-gas-glow)"/>${arms}<ellipse rx="${size*.22}" ry="${size*.15}" fill="#f2dba5"/><circle r="${size*.08}" fill="#fff3ce"/></g>`;
}
function ctGalaxies(t){
 const galaxies=[[105,135,39,25],[274,205,38,-23],[438,121,34,-35],[604,204,42,15],[667,113,22,-30]].map(([x,y,s,r],i)=>ctSpiral(x,y,s,r+Math.sin(t*.05+i)*1.4)).join('');
 return `${ctDots(115,t,{radius:.85,color:'#dce9ee',opacity:.28,speed:.006})}${galaxies}`;
}
function ctSolarSystem(t){
 const sunX=351,sunY=180,orbits=[[52,19,2.6,'#c8b6a3',.3],[86,35,5.3,'#c6ba97',.22],[132,54,6,'#74adc1',.15],[190,78,8.4,'#e1b98e',.09]];
 const planets=orbits.map(([a,b,r,color,speed],i)=>{const phase=t*speed+i*1.2;return `<ellipse cx="${sunX}" cy="${sunY}" rx="${a}" ry="${b}" fill="none" stroke="#aec8d3" stroke-opacity=".23"/><circle cx="${(sunX+a*Math.cos(phase)).toFixed(2)}" cy="${(sunY+b*Math.sin(phase)).toFixed(2)}" r="${r}" fill="${color}"/>`;}).join('');
 return `${ctDots(100,t,{radius:.8,color:'#deedf2',opacity:.28,speed:.004})}${ctSpiral(93,125,20,-35,.2)}${ctSpiral(660,226,23,18,.2)}${planets}<g transform="translate(${sunX} ${sunY})"><circle r="74" fill="url(#ct-star-glow)"/><circle r="22" fill="#f2d17e"/><circle r="19" fill="#ffe5a0"/></g>`;
}
function ctCosmicWeb(t){
 const centers=[[91,132],[183,224],[304,139],[437,216],[537,116],[660,189],[345,247],[704,101]],connections=[[0,1],[0,2],[1,2],[1,6],[2,3],[2,4],[3,4],[3,5],[3,6],[4,5],[4,7],[5,7]];
 const filaments=connections.map(([a,b])=>{const p=centers[a],q=centers[b],midX=(p[0]+q[0])/2,midY=(p[1]+q[1])/2-12;return `<path d="M${p[0]} ${p[1]}Q${midX} ${midY} ${q[0]} ${q[1]}" fill="none" stroke="#749cba" stroke-width="18" stroke-linecap="round" opacity=".08"/><path d="M${p[0]} ${p[1]}Q${midX} ${midY} ${q[0]} ${q[1]}" fill="none" stroke="#92b9cf" stroke-width="2" opacity=".18"/>`;}).join('');
 const groups=centers.map(([x,y],i)=>Array.from({length:3+i%3},(_,j)=>{const a=j*2.4+i,dist=j===0?0:13+j*2;return ctSpiral(x+Math.cos(a)*dist,y+Math.sin(a)*dist,8+j%3*2,i*37+j*13+Math.sin(t*.03)*.5,.8);}).join('')).join('');
 return `${ctDots(105,t,{radius:.75,color:'#d4e4f1',opacity:.24,speed:.003})}${filaments}${groups}`;
}
const ctDrawers=[ctQuarkSoup,ctBaryonField,ctNuclei,ctAtoms,ctFirstStars,ctGalaxies,ctSolarSystem,ctCosmicWeb];
const ctBackgrounds=['#492d33','#393241','#263848','#203946','#142d3d','#142938','#142938','#142938'];

export function mountUniverseTimeline(root,api){
 const find=id=>root.querySelector(`#${id}`),slider=find('ct-epoch'),scene=find('ct-scene');
 if(!slider||!scene)return ()=>{};
 let index=0;
 const previous=find('ct-previous'),next=find('ct-next'),draw=t=>{scene.innerHTML=ctDrawers[index](t);};
 const setEpoch=value=>{
  const epoch=getUniverseEpoch(value);index=universeEpochs.indexOf(epoch);slider.value=String(index);
  slider.setAttribute('aria-valuetext',`${epoch.age}: ${epoch.short}`);
  find('ct-epoch-value').textContent=`${index+1} av ${universeEpochs.length} · ${epoch.short}`;
  find('ct-age').textContent=epoch.age;find('ct-temperature').textContent=epoch.temperatureText;find('ct-temperature-label').textContent=epoch.temperatureLabel;
  find('ct-scene-title').textContent=epoch.name;find('ct-scene-legend').textContent=epoch.legend;find('ct-scene-scale').textContent=epoch.scale;
  find('ct-scene-background').setAttribute('fill',ctBackgrounds[index]);
  find('ct-figure-title').textContent=epoch.name;find('ct-figure-desc').textContent=`${epoch.age}. ${epoch.structure}. ${epoch.description}`;
  find('ct-description').innerHTML=`${epoch.description}<strong class="ct-cause">${epoch.change}</strong>`;
  previous.disabled=index===0;next.disabled=index===universeEpochs.length-1;api.repaint(scene);
 };
 const onInput=()=>setEpoch(slider.value),onPrevious=()=>setEpoch(index-1),onNext=()=>setEpoch(index+1);
 slider.addEventListener('input',onInput);previous.addEventListener('click',onPrevious);next.addEventListener('click',onNext);
 const removeFrame=api.onFrame(draw,scene);setEpoch(0);
 return ()=>{removeFrame?.();slider.removeEventListener('input',onInput);previous.removeEventListener('click',onPrevious);next.removeEventListener('click',onNext);};
}
